// Mutate owned temporary copies only: transferred generated bytes stay exact.
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { createHash } from 'node:crypto'
import { prove } from './review-revert.mjs'
const root = '.tmp/profile-data-removals'
mkdirSync(root, { recursive: true, mode: 0o700 })
const originalPath = 'src/api/agent-profile-contract.ts'
const original = readFileSync(originalPath)
const file = root + '/agent-profile-contract.ts'
copyFileSync(originalPath, file)
copyFileSync(
  'src/api/agent-profile-canonical.ts',
  root + '/agent-profile-canonical.ts',
)
const previousSubject = process.env.TEST_GILD_PROFILE_CONTRACT
process.env.TEST_GILD_PROFILE_CONTRACT = resolve(file)
const suite = 'src/api/agent-profile-data.test.ts'
const cases = [
  [
    'missing-precondition',
    (s) =>
      s.replace(
        "if (!own) throw new AgentProfileContractError('PRECONDITION_REQUIRED', 428)",
        'if (!own) return',
      ),
    'own profile preconditions',
  ],
  [
    'stale-precondition',
    (s) => s.replace('if (own.value !== currentRevisionId)', 'if (false)'),
    'own profile preconditions',
  ],
  [
    'stale-before-canonical',
    (s) =>
      s.replace(
        '  if (own.value !== currentRevisionId)',
        "  try { canonicalBytes(value) } catch { throw new AgentProfileContractError('VALIDATION_FAILED', 422) }\n  if (own.value !== currentRevisionId)",
      ),
    'replacement and rollback stale revisions',
  ],
  [
    'owner-generation',
    (s) =>
      s.replace(
        'snapshot.ownerIdentityId !== profile.ownerIdentityId',
        'false',
      ),
    'snapshot binds exact profile',
  ],
  [
    'profile-digest',
    (s) =>
      s.replace(
        'snapshot.profileDigest !== await canonicalDigest(profile)',
        'false',
      ),
    'snapshot binds exact profile',
  ],
  [
    'support-digest',
    (s) =>
      s.replace(
        'snapshot.supportReportDigest !== await canonicalDigest(report)',
        'false',
      ),
    'snapshot binds exact profile',
  ],
  [
    'complete-skill-binding',
    (s) =>
      s.replace(
        'await verifySkillSelection(selection, manifest)',
        'void selection; void manifest',
      ),
    'snapshot requires complete ordered',
  ],
  [
    'delivery-declaration',
    (s) =>
      s.replace(
        "report.delivery.status !== 'verified' || !report.delivery.modes.includes(mode)",
        'false',
      ),
    'discovery cannot substitute',
  ],
  [
    'required-control',
    (s) =>
      s.replace('profile.desiredControls[key].requireEnforced &&', 'false &&'),
    'each required control rejects',
  ],
]
try {
  const evidence = cases.map(([name, mutate, pattern]) =>
    prove('profile-data-' + name, file, mutate, suite, pattern),
  )
  if (!readFileSync(originalPath).equals(original))
    throw Error('Tracked generated artifact changed')
  if (!readFileSync(file).equals(original))
    throw Error('Temporary subject not restored')
  writeFileSync(
    '.tmp/profile-data-revert-evidence.json',
    JSON.stringify(
      {
        canonicalCommit: '9142ecd8858dca7d5a37f909869a05ad513f0c1b',
        outputSha256: createHash('sha256').update(original).digest('hex'),
        trackedUnchanged: true,
        temporaryRestored: true,
        evidence,
      },
      null,
      2,
    ) + '\n',
  )
  console.log(JSON.stringify(evidence))
} finally {
  writeFileSync(file, original)
  if (previousSubject === undefined)
    delete process.env.TEST_GILD_PROFILE_CONTRACT
  else process.env.TEST_GILD_PROFILE_CONTRACT = previousSubject
}
